import json, sys

f = "/Users/marcel.a.n.navarro/.claude/projects/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/40c4f2c3-4027-4ed9-b2a0-3e5b75096ce2/tool-results/mcp-mcp-atlassian-jira_search-1785900442611.txt"
d = json.load(open(f))
issues = json.loads(d["result"])
if isinstance(issues, dict):
    issues = issues.get("issues", [])

rows = []
for it in issues:
    if not isinstance(it, dict):
        continue
    key = it.get("key", "")
    summ = it.get("summary", "")
    st = (it.get("status") or {}).get("name", "")
    ty = (it.get("issue_type") or {}).get("name", "")
    pr = (it.get("priority") or {}).get("name", "")
    par = it.get("parent") or {}
    pk = par.get("key", "")
    ps = (par.get("fields") or {}).get("summary", "")
    labels = ",".join(it.get("labels", []) or [])
    rows.append((key, ty, st, pr, pk, ps, summ, labels))

# sort by numeric key descending
def num(k):
    try:
        return int(k.split("-")[1])
    except Exception:
        return 0

for key, ty, st, pr, pk, ps, summ, labels in sorted(rows, key=lambda r: num(r[0]), reverse=True):
    print(f"{key:9} | {ty:6} | {st:12} | {pr:7} | epic:[{pk} {ps}] | {summ}  <{labels}>")

